def make(n):
    chars = string.ascii_letters + string.digits
    return [
        [random.choice(chars) for _ in range(math.ceil(math.log2(i + 2)))]
        for i in range(min(n, 8))
    ]

def make(n):
    sizes = list(range(1, min(n, 8) + 1))
    return [
        [str(s)]
        for s in sizes
    ]

def make(n):
    ops = list(range(1, min(n, 8) + 1))
    return [ [op] for op in ops ]
